def sum_multiples(n):
    k = n // 3
    return 3 * k * (k + 1) // 2

def clamp_list(values, lo, hi):
    result = []
    for value in values:
        if value < lo:
            result.append(lo)
        elif value > hi:
            result.append(hi)
        else:
            result.append(value)
    return result
